parameters.jsCode:
let raw = $input.first().json.output || $input.first().json.text || $input.first().json.message?.content || '{}';

try {
  if (typeof raw === 'string') {
    const cleaned = raw.replace(/```json/g, '').replace(/```/g, '').trim();
    const parsed = JSON.parse(cleaned);
    return [ { json: parsed } ];
  } else {
    return [ { json: raw } ];
  }
} catch (e) {
  return [ {
    json: {
      title: "Consejo del Entrenador AI",
      content_es: String(raw),
      source: "N8N_WORKFLOW"
    }
  } ];
}
